/*!50003 CREATE*/ /*!50017 DEFINER=`ContainerMgmt`@`%`*/ /*!50003 TRIGGER `set_status_before_INSERT` BEFORE INSERT ON `container_details` FOR EACH ROW BEGIN
 DECLARE arrival_date DATE;

--  Fetch the ArrivalDate from bill_of_landing
 SELECT ArrivalDate INTO arrival_date
 FROM bill_of_landing
 WHERE BillOfLanding = NEW.BillOfLanding
 LIMIT 1;

--  Set status based on logic
 IF NEW.out_bound IS NOT NULL OR NEW.unloaded_at_port IS NOT NULL THEN
 SET NEW.status = 4; -- Complete
 ELSEIF NEW.empty_date IS NOT NULL THEN
 SET NEW.status = 7; -- Empty
 ELSEIF NEW.in_bound IS NOT NULL THEN
 SET NEW.status = 6; -- Inbound
 ELSEIF arrival_date IS NULL THEN
 SET NEW.status = 8; -- Unknown (fallback)
 ELSEIF arrival_date > CURDATE() THEN
 SET NEW.status = 1; -- In Transit
 ELSE
 SET NEW.status = 2; -- On Port
 END IF;
END */;;
DELIMITER ;
