/*!50003 CREATE*/ /*!50017 DEFINER=`ContainerMgmt`@`%`*/ /*!50003 TRIGGER `set_status_before_UPDATE` BEFORE UPDATE ON `container_details` FOR EACH ROW trigger_body: BEGIN
 DECLARE arrival_date DATE;

-- ✅ Allow status update from 2 (On Port) to 3 (Gate Pass) manually
 IF OLD.status = 2 AND NEW.status = 3 THEN
 LEAVE trigger_body; -- exits before overriding NEW.status
 END IF;

-- ✅ Fetch the ArrivalDate from bill_of_landing
 SELECT ArrivalDate INTO arrival_date
 FROM bill_of_landing
 WHERE BillOfLanding = NEW.BillOfLanding
 LIMIT 1;

-- ✅ Nested IF logic to determine status
 IF NEW.out_bound IS NOT NULL OR NEW.unloaded_at_port IS NOT NULL THEN
 SET NEW.status = 4;
 ELSEIF NEW.empty_date IS NOT NULL THEN
 SET NEW.status = 7;
 ELSEIF NEW.in_bound IS NOT NULL THEN
 SET NEW.status = 6;
 ELSEIF arrival_date > CURDATE() THEN
 SET NEW.status = 1;
 ELSEIF arrival_date <= CURDATE() THEN
 SET NEW.status = 2;
 ELSE
 -- Fallback
 SET NEW.status = 8;
 END IF;

END */;;
DELIMITER ;
