CREATE TABLE `container_details02` (
  `Container_ID` int NOT NULL AUTO_INCREMENT,
  `container_no` varchar(50) NOT NULL,
  `supplier` int DEFAULT NULL,
  `material` text,
  `docs` int DEFAULT NULL,
  `type` int DEFAULT NULL,
  `in_bound` datetime DEFAULT NULL,
  `emptied_at` int DEFAULT NULL,
  `empty_date` date DEFAULT NULL,
  `out_bound` datetime DEFAULT NULL,
  `unloaded_at_port` date DEFAULT NULL,
  `note` text,
  `status` int DEFAULT NULL,
  `consignee` int DEFAULT NULL,
  `tax` smallint DEFAULT NULL,
  `PONo` varchar(45) DEFAULT NULL,
  `VessalID` int DEFAULT NULL,
  `Arrival_Date` date DEFAULT NULL,
  PRIMARY KEY (`Container_ID`),
  KEY `supplier` (`supplier`),
  KEY `docs` (`docs`),
  KEY `type` (`type`),
  KEY `emptied_at` (`emptied_at`),
  KEY `consignee` (`consignee`),
  KEY `container_details_ibfk_6` (`VessalID`),
  CONSTRAINT `container_details02_ibfk_1` FOREIGN KEY (`supplier`) REFERENCES `supplier` (`supplier_id`),
  CONSTRAINT `container_details02_ibfk_2` FOREIGN KEY (`docs`) REFERENCES `shipping_document` (`doc_id`),
  CONSTRAINT `container_details02_ibfk_3` FOREIGN KEY (`type`) REFERENCES `container_type` (`type_id`),
  CONSTRAINT `container_details02_ibfk_4` FOREIGN KEY (`emptied_at`) REFERENCES `unload_venue` (`venue_id`),
  CONSTRAINT `container_details02_ibfk_5` FOREIGN KEY (`consignee`) REFERENCES `consignee` (`consignee_id`),
  CONSTRAINT `container_details02_ibfk_6` FOREIGN KEY (`VessalID`) REFERENCES `vessals` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1612 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
